public class Solution {
    public static int sumSkipNeg(int[] arr) {
        // CONTRACT: sum of the NON-NEGATIVE elements only.
        int total = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < 0) {
                total += arr[i];
            }
        }
        return total;
    }
}

